mapper.select:
   select ci.id,ci.name,ci.crt_time crtTime,pt.name pName from coupon_common_info ci
    left join product_type pt on ci.product_type_id = pt.id
--     left join (select MAX(crt_time),path,coupon_id from coupon_file_info group by coupon_id) cf on cf.coupon_id = ci.id
    where  ci.type = #{type}

          and ci.product_type_id = #{productTypeId}


      and ci.name like concat('%', #{name}, '%')


      and ci.crt_time between #{startTime} and #{endTime}
